public class Main {
    static boolean isPerfectNumber(int num) {
        if (num <= 1) return false;
        long total = 0;
        for (int i = 1; i < num; i++) {          // every candidate from 1 to num - 1
            if (num % i == 0) total += i;
        }
        return total == num;
    }
}

