def is_perfect_number(num):
    if num <= 1:
        return False
    total = 1                                # 1 always divides num (for num > 1)
    i = 2
    while i * i <= num:
        if num % i == 0:
            total += i
            if i != num // i:
                total += num // i            # the pair partner, unless it's the same value
        i += 1
    return total == num

